import{_ as a,o,c as r,a3 as e}from"./chunks/framework.B9qR_F1m.js";const c=JSON.parse('{"title":"议论文结构","description":"给出议论文从审题立意到成篇的完整骨架：三种常见结构、论据选取标准、段落内部展开方式，以及语言升格技巧。","frontmatter":{"title":"议论文结构","date":"2026-10-14T00:00:00.000Z","subject":"chinese","subjectLabel":"语文","category":"写作方法","tags":["议论文","作文结构","论据"],"description":"给出议论文从审题立意到成篇的完整骨架：三种常见结构、论据选取标准、段落内部展开方式，以及语言升格技巧。"},"headers":[],"relativePath":"subjects/chinese/writing/argumentative-essay.md","filePath":"subjects/chinese/writing/argumentative-essay.md","lastUpdated":null}'),n={name:"subjects/chinese/writing/argumentative-essay.md"};function s(l,t,i,d,u,h){return o(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="议论文结构" tabindex="-1">议论文结构 <a class="header-anchor" href="#议论文结构" aria-label="Permalink to &quot;议论文结构&quot;">​</a></h1><blockquote><p><strong>一句话概括</strong>：议论文的竞争力不在辞藻，而在&quot;论点是否站得住、论证是否推进了&quot;。</p></blockquote><h2 id="一、审题立意" tabindex="-1">一、审题立意 <a class="header-anchor" href="#一、审题立意" aria-label="Permalink to &quot;一、审题立意&quot;">​</a></h2><h3 id="四步审题" tabindex="-1">四步审题 <a class="header-anchor" href="#四步审题" aria-label="Permalink to &quot;四步审题&quot;">​</a></h3><ol><li><strong>辨题型</strong>：材料作文、命题作文、话题作文、漫画作文；</li><li><strong>抓关键</strong>：圈出材料中的高频词、转折词（&quot;然而&quot;&quot;但&quot;）与价值判断词；</li><li><strong>定范围</strong>：材料要求谈&quot;个人成长&quot;还是&quot;社会现象&quot;，不要越界；</li><li><strong>找角度</strong>：从材料中至少列出三个可选角度，再挑最有话说的那个。</li></ol><h3 id="立意的三个标准" tabindex="-1">立意的三个标准 <a class="header-anchor" href="#立意的三个标准" aria-label="Permalink to &quot;立意的三个标准&quot;">​</a></h3><ul><li><strong>准</strong>：不偏题，与材料核心词保持一致；</li><li><strong>深</strong>：不停留在&quot;要努力&quot;这类常识层面，追问&quot;为什么&quot;&quot;怎么办&quot;；</li><li><strong>新</strong>：在常规观点基础上增加一个限定条件，例如把&quot;坚持&quot;具体到&quot;有方向的坚持&quot;。</li></ul><p>中心论点必须是一句<strong>完整的陈述句</strong>，包含判断词（是、需要、决定、意味着）。</p><h2 id="二、三种常用结构" tabindex="-1">二、三种常用结构 <a class="header-anchor" href="#二、三种常用结构" aria-label="Permalink to &quot;二、三种常用结构&quot;">​</a></h2><h3 id="结构一-并列式-是什么—为什么—怎么办" tabindex="-1">结构一：并列式（是什么—为什么—怎么办） <a class="header-anchor" href="#结构一-并列式-是什么—为什么—怎么办" aria-label="Permalink to &quot;结构一：并列式（是什么—为什么—怎么办）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>引论：概述材料，提出中心论点</span></span>
<span class="line"><span>本论：</span></span>
<span class="line"><span>  分论点①：是什么（界定概念）</span></span>
<span class="line"><span>  分论点②：为什么（分析原因与意义）</span></span>
<span class="line"><span>  分论点③：怎么办（提出路径）</span></span>
<span class="line"><span>结论：升华主旨，回应现实</span></span></code></pre></div><h3 id="结构二-层进式-现象—危害—根源—对策" tabindex="-1">结构二：层进式（现象—危害—根源—对策） <a class="header-anchor" href="#结构二-层进式-现象—危害—根源—对策" aria-label="Permalink to &quot;结构二：层进式（现象—危害—根源—对策）&quot;">​</a></h3><p>适合评析社会现象类材料，四个环节逐层深入，逻辑推进感最强。</p><h3 id="结构三-正反对照式-正面论证-反面论证-辨析" tabindex="-1">结构三：正反对照式（正面论证 + 反面论证 + 辨析） <a class="header-anchor" href="#结构三-正反对照式-正面论证-反面论证-辨析" aria-label="Permalink to &quot;结构三：正反对照式（正面论证 + 反面论证 + 辨析）&quot;">​</a></h3><p>先正面立论，再设想反面情形，最后用&quot;或曰……然而……&quot;进行让步反驳， 使论证更严密，不容易被驳倒。</p><h2 id="三、段落内部展开" tabindex="-1">三、段落内部展开 <a class="header-anchor" href="#三、段落内部展开" aria-label="Permalink to &quot;三、段落内部展开&quot;">​</a></h2><p>推荐使用「<strong>论点句 — 阐释句 — 事例句 — 分析句 — 结论句</strong>」五步法：</p><ul><li><strong>论点句</strong>：放在段首，一句话说清本段主张；</li><li><strong>阐释句</strong>：解释关键词的含义，或说明为什么这样说；</li><li><strong>事例句</strong>：概括论据，控制在 60 字以内，只保留与论点相关的部分；</li><li><strong>分析句</strong>：这是最关键的一步——说明&quot;这个事例为什么能证明论点&quot;， 常用方法：假设分析（&quot;假如没有……就不会……&quot;）、因果分析、对比分析；</li><li><strong>结论句</strong>：回扣分论点，最好能呼应中心论点。</li></ul><blockquote><p><strong>提醒</strong>：缺少&quot;分析句&quot;是议论文最常见的失分点。只摆事例不作分析， 事例与论点之间就缺少逻辑连接。</p></blockquote><h2 id="四、论据的选取" tabindex="-1">四、论据的选取 <a class="header-anchor" href="#四、论据的选取" aria-label="Permalink to &quot;四、论据的选取&quot;">​</a></h2><h3 id="三条标准" tabindex="-1">三条标准 <a class="header-anchor" href="#三条标准" aria-label="Permalink to &quot;三条标准&quot;">​</a></h3><ol><li><strong>真实准确</strong>：人物、时间、数字不能出错，拿不准就改用熟悉的素材；</li><li><strong>贴切对口</strong>：素材的核心特质必须与论点一致，不贴切的宁可不用；</li><li><strong>新颖适度</strong>：避开被写烂的例子，或在使用角度上出新。</li></ol><h3 id="素材分类储备" tabindex="-1">素材分类储备 <a class="header-anchor" href="#素材分类储备" aria-label="Permalink to &quot;素材分类储备&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>建议储备数量</th><th>示例方向</th></tr></thead><tbody><tr><td>古代人物</td><td>3—5 个</td><td>苏轼、司马迁、王阳明</td></tr><tr><td>近现代人物</td><td>3—5 个</td><td>钱学森、袁隆平、屠呦呦</td></tr><tr><td>当代热点</td><td>2—3 组</td><td>科技攻关、乡村振兴、文化传承</td></tr><tr><td>名言警句</td><td>10 句左右</td><td>按&quot;坚持&quot;&quot;创新&quot;&quot;担当&quot;等主题分类</td></tr></tbody></table><p>一个素材要能从<strong>不同角度</strong>解读，例如袁隆平既可用于&quot;梦想&quot;，也可用于&quot;脚踏实地&quot;&quot;科学精神&quot;。</p><h2 id="五、语言升格" tabindex="-1">五、语言升格 <a class="header-anchor" href="#五、语言升格" aria-label="Permalink to &quot;五、语言升格&quot;">​</a></h2><ol><li><strong>化抽象为具象</strong>：把&quot;坚持&quot;写成&quot;把一件事重复一万次而不改其志&quot;；</li><li><strong>善用短句与整句</strong>：议论段中适当插入整散结合的句式，增强节奏感；</li><li><strong>准确使用关联词</strong>：让逻辑关系显性化（&quot;并非……而是……&quot;&quot;与其……不如……&quot;）；</li><li><strong>控制修辞密度</strong>：议论文以说理为主，修辞服务于表达，不必堆砌。</li></ol><h2 id="六、开头与结尾" tabindex="-1">六、开头与结尾 <a class="header-anchor" href="#六、开头与结尾" aria-label="Permalink to &quot;六、开头与结尾&quot;">​</a></h2><h3 id="开头三法" tabindex="-1">开头三法 <a class="header-anchor" href="#开头三法" aria-label="Permalink to &quot;开头三法&quot;">​</a></h3><ul><li><strong>引材点睛</strong>：简述材料后直接点明论点，最稳妥；</li><li><strong>设问引入</strong>：以问题开头，引发思考后作答；</li><li><strong>场景切入</strong>：用简短的画面描写引入，再过渡到议论。</li></ul><h3 id="结尾三法" tabindex="-1">结尾三法 <a class="header-anchor" href="#结尾三法" aria-label="Permalink to &quot;结尾三法&quot;">​</a></h3><ul><li><strong>回应式</strong>：回扣开头与材料，形成闭环；</li><li><strong>升华式</strong>：从个人推及社会、时代、文明；</li><li><strong>呼告式</strong>：发出号召，增强感染力，但要避免空洞口号。</li></ul><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误区</th><th>修正</th></tr></thead><tbody><tr><td>论点散在全文，没有一句话概括</td><td>中心论点必须独立成句，置于醒目位置</td></tr><tr><td>三个分论点互相交叉</td><td>分论点之间应并列或层进，不重叠</td></tr><tr><td>事例写成了记叙文</td><td>议论文中事例只需概括，重心在分析</td></tr><tr><td>结尾重抄开头</td><td>结尾应升华而非重复</td></tr></tbody></table><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>叶圣陶《怎样写作》</li><li>《高考满分作文》结构解析部分</li></ul>`,36)])])}const g=a(n,[["render",s]]);export{c as __pageData,g as default};
